const allPostsItems = $items('1. Get All Existing Post IDs');
const processedItems = $items('2. Get Processed Link IDs');
const embeddingItems = $items('3. Get ALL Embedding Data (ONCE)');


const allPostIds = new Set(allPostsItems.map(item => String(item.json['Post ID'])));
const processedPostIds = new Set(processedItems.map(item => String(item.json['Post ID'])));
const allEmbeddings = embeddingItems.map(item => item.json);


for (const id of processedPostIds) {
    allPostIds.delete(id);
}
const unprocessedIds = Array.from(allPostIds).slice(0, 7);

if (unprocessedIds.length === 0) {
    return [];
}


const output = unprocessedIds.map(id => {

    const postData = allEmbeddings.find(p => String(p['Post ID']) === id);
    return {
        json: {
            ...postData, 
            'allEmbeddingsData': allEmbeddings
        }
    };
}).filter(item => item.json['Post URL']); 

return output;

// --- 1. دریافت داده‌ها ---
const mergedData = $json;
const liveHtmlContent = mergedData.body;
const currentPostDataFromSheet = mergedData;
const allEmbeddingsData = mergedData.allEmbeddingsData;

// --- 2. توابع کمکی ---

// گرفتن ریشه دامنه
const getBaseUrl = (url) => {
    try {
        const urlObject = new URL(url);
        return `${urlObject.protocol}//${urlObject.hostname.replace(/^www\./, '')}`;
    } catch (e) {
        return 'https://oabeans.com';
    }
};

// تابع نرمالایز قدرتمند
const normalizeUrl = (url) => {
    if (typeof url !== 'string' || url.startsWith('#') || !url.trim()) return '';
    try {
        let urlObject = new URL(url);
        // حذف www.
        let hostname = urlObject.hostname.replace(/^www\./, '');
        // حذف اسلش آخر و پارامتر
        let path = urlObject.pathname.replace(/\/$/, "");
        return `${urlObject.protocol}//${hostname}${path}`.toLowerCase();
    } catch (e) {
        return '';
    }
};

// استخراج لینک‌ها از html (فقط url)
const extractLinks = (htmlContent, baseUrl) => {
    if (typeof htmlContent !== 'string') return [];
    const regex = /<a\s+(?:[^>]*?\s+)?href=([\"'])(.*?)\1/gi;
    const matches = new Set();
    let match;
    while ((match = regex.exec(htmlContent)) !== null) {
        let href = match[2];
        if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:')) {
            continue;
        }
        let fullUrl;
        if (href.startsWith('http')) {
            fullUrl = href;
        } else if (href.startsWith('/')) {
            fullUrl = baseUrl + href;
        } else {
            continue;
        }
        const normalized = normalizeUrl(fullUrl);
        if (normalized) {
            matches.add(normalized);
        }
    }
    return Array.from(matches);
};

// استخراج anchor+url از html
const extractAnchorsWithUrls = (htmlContent, baseUrl) => {
    if (typeof htmlContent !== 'string') return [];
    const regex = /<a\s+[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    const result = [];
    let match;
    while ((match = regex.exec(htmlContent)) !== null) {
        let href = match[1];
        let text = match[2].replace(/<[^>]+>/g, '').trim(); // حذف تگ‌های داخل anchor
        if (!href || !text) continue;
        let fullUrl = href.startsWith('http') ? href : baseUrl + href;
        let normalized = normalizeUrl(fullUrl);
        if (normalized && text) {
            result.push({ url: normalized, anchor: text });
        }
    }
    return result;
};

// similarity
const calculateSimilarity = (vecA_str, vecB_str) => {
    try {
        const vecA = JSON.parse(vecA_str); 
        const vecB = JSON.parse(vecB_str);
        if (!Array.isArray(vecA) || !Array.isArray(vecB) || vecA.length !== vecB.length) return 0;
        let d = 0, mA = 0, mB = 0;
        for (let i = 0; i < vecA.length; i++) { 
            d += (vecA[i] || 0) * (vecB[i] || 0); 
            mA += (vecA[i] || 0) ** 2; 
            mB += (vecB[i] || 0) ** 2; 
        }
        mA = Math.sqrt(mA); 
        mB = Math.sqrt(mB);
        if (mA === 0 || mB === 0) return 0;
        return d / (mA * mB);
    } catch (e) { return 0; }
};


const baseUrl = getBaseUrl(currentPostDataFromSheet['Post URL']);


const existingLinks = extractLinks(liveHtmlContent, baseUrl)
    .map(normalizeUrl)
    .filter(Boolean);
const existingLinksSet = new Set(existingLinks);


const existingAnchors = extractAnchorsWithUrls(liveHtmlContent, baseUrl);


const linkableCandidates = allEmbeddingsData
    .filter(p => p && p.Embedding && p['Post URL'])
    .filter(p => String(p['Post ID']) !== String(currentPostDataFromSheet['Post ID']))
    .filter(p => !existingLinksSet.has(normalizeUrl(p['Post URL'])));

const finalSuggestions = linkableCandidates
    .map(p => ({ ...p, similarity: calculateSimilarity(currentPostDataFromSheet.Embedding, p.Embedding) }))
    .filter(p => p.similarity > 0.45)
    .sort((a, b) => b.similarity - a.similarity)
    .slice(0, 5);


const usedAnchorsArr = existingAnchors.map(item => ({
    anchor: item.anchor,
    url: item.url
}));

const linkablePostsString = finalSuggestions.map(p => `Title: ${p['Post Title']}\nURL: ${p['Post URL']}`).join('\n---\n');

return [{
    json: {
        currentPostData: currentPostDataFromSheet,
        linkablePostsString: linkablePostsString,
        existingLinks: existingLinks,
        usedAnchorsArr: usedAnchorsArr 
    }
}];

// --- 1. دریافت داده‌ها ---
const inputData = $json;
const mainPostContent = inputData.currentPostData ? inputData.currentPostData['Plain Text Content'] : 'No content available.';
const linkablePosts = inputData.linkablePostsString || 'No candidates available.';
const currentPostTitle = inputData.currentPostData ? inputData.currentPostData['Post Title'] : '';
const usedAnchorsArr = inputData.usedAnchorsArr || [];

// تبدیل usedAnchorsArr به فرمت قابل‌خواندن توسط AI
const usedAnchorsString = usedAnchorsArr.length === 0
    ? '[]'
    : usedAnchorsArr.map(x => `Anchor: "${x.anchor}"   |   URL: ${x.url}`).join('\n');

// --- 2. ساخت پرامپت جدید با قوانین سخت‌گیرانه برای سئو و anti-duplicate anchor+url ---
const prompt = `
You are a senior SEO strategist. Your priority is user experience and adding genuine value.
Your task is to analyze the 'Main Post Content' and suggest up to 3 highly relevant internal links from the 'Link Candidates'.

**CRITICAL RULES YOU MUST FOLLOW:**

1.  **ADD VALUE, DON'T REPEAT:** The suggested link MUST offer new, supplementary information. It should answer a logical next question or expand on a related sub-topic.
2.  **AVOID REDUNDANT LINKS:**
    *   **NO GENERAL FROM SPECIFIC:** Do NOT link from a specific article (e.g., "Ungating in LEGO") to a more general one (e.g., "Ungating in Toys" or "What is Ungating?"). This is a bad user experience.
    *   Do not suggest a link if its topic is already the main subject of the current article.

3.  **STRICT ANCHOR TEXT RULES:**
    *   The anchor text MUST be a specific, descriptive phrase (3-7 words) that accurately reflects the target page's content.
    *   The anchor text MUST be selected DIRECTLY from the 'Main Post Content'. DO NOT invent or rephrase it.
    *   **FORBIDDEN ANCHORS:** Absolutely NO generic phrases like "gain more profits", "click here", "read more", "learn more", "this article", etc.

4.  **NO DUPLICATE ANCHOR LINKS:**  
    *   If an anchor text in 'Main Post Content' is already hyperlinked to a certain URL (as shown in the list below), you are absolutely FORBIDDEN from suggesting the same anchor text to the same URL again—even if it appears elsewhere in the content without a link.  
    *   Here is the list of currently linked anchor texts and their URLs. DO NOT suggest these pairs again:\n${usedAnchorsString}

5.  **OUTPUT FORMATTING:**
    *   Return ONLY a valid JSON object with a single key "suggestions", which is an array of objects.
    *   Each object MUST have these 4 keys: "anchorText", "link", "reason", and "contextualSentence".
    *   "contextualSentence" MUST be the full sentence from the 'Main Post Content' where your chosen "anchorText" is located.
    *   "reason" must briefly explain WHY the link adds value to the reader, following the rules above.

---
**Current Article Title:**
${currentPostTitle}

---
**Main Post Content (Source):**
${mainPostContent}

---
**Link Candidates (Destinations):**
${linkablePosts}
---
`;

return [{
    json: {
        model: 'gpt-4o',
        messages: [
            { role: 'system', content: 'You are a world-class SEO strategist that outputs only valid JSON, strictly following all user-defined rules without exception.' },
            { role: 'user', content: prompt }
        ],
        response_format: { type: 'json_object' }
    }
}];

let suggestions_to_log = [];
const sourcePost = $items('5. Process & Find Similar')[0].json.currentPostData;

try {
    const cleanContent = $json.choices[0].message.content.trim();
    const response = JSON.parse(cleanContent);

    if (response && Array.isArray(response.suggestions)) {
        suggestions_to_log = response.suggestions

            .filter(s => s && s.anchorText && s.link && s.contextualSentence)
            .map(s => ({
                json: {
                    anchorText: s.anchorText,
                    link: s.link,
                    reason: s.reason || 'No reason provided',

                    contextualSentence: s.contextualSentence,
                    sourcePostId: sourcePost['Post ID'],
                    sourcePostTitle: sourcePost['Post Title'],
                    sourceURL: sourcePost['Post URL']
                }
            }));
    }
} catch (e) {
    console.error("Error processing AI response:", e.message);
    return []; 
}

if (suggestions_to_log.length === 0) {
    return [];
}
return suggestions_to_log;
